// Stem returns the Hungarian Snowball stem of input.
func Stem(input string) string {
	normalized := snowball.Normalize(input)
	return stemRaw(normalized)
}

func stemRaw(input string) string {
	var instance stemmer
	var buffer [snowball.InlineBufferCapacity]byte
	instance.env.InitWithBuffer(input, buffer[:])
	instance.routineStem()
	return instance.env.Result(input)
}

// IsStopWord reports whether input is a Hungarian stop word.
func IsStopWord(input string) bool {
	normalized := snowball.Normalize(input)
	_, found := stopWordSet[normalized]
	return found
}

// StopWords returns a sorted copy of the Hungarian stop word list.
func StopWords() []string {
	return slices.Clone(stopWordList)
}

